// original.cs — a signup endpoint that does the framework's job by hand:
// it reads the raw body stream, parses the JSON itself, digs out each field,
// and validates with early returns — a different error shape (all 200 OK!)
// at every exit. A second endpoint hand-parses query strings with int.Parse.
//
// Run:   dotnet run csharp/17-model-binding-validation/original.cs
// Then:  curl -X POST http://localhost:5017/signup -H "Content-Type: application/json" -d "{}"

using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapPost("/signup", async (HttpRequest req) =>
{
    // Step 1: read and parse the body OURSELVES (the framework would have
    // happily done this — see js#65, where we had no choice).
    JsonDocument doc;
    try
    {
        doc = await JsonDocument.ParseAsync(req.Body);
    }
    catch (JsonException)
    {
        return Results.Json(new { ok = false, problem = "body was not valid json" }); // 200!
    }

    using (doc)
    {
        var root = doc.RootElement;

        // Step 2: dig out each field by hand and bail at the FIRST problem.
        // Error shape #1: { ok, problem }
        if (!root.TryGetProperty("email", out var emailProp) || emailProp.ValueKind != JsonValueKind.String)
            return Results.Json(new { ok = false, problem = "no email" });              // 200!

        var email = emailProp.GetString()!;
        // Error shape #2: { error } — a different author, a different day
        if (!email.Contains("@") || email.StartsWith("@") || email.EndsWith("@"))
            return Results.Json(new { error = "email looks wrong" });                   // 200!

        if (!root.TryGetProperty("password", out var passProp) || passProp.ValueKind != JsonValueKind.String)
            return Results.Json(new { ok = false, problem = "no password" });           // 200!

        var password = passProp.GetString()!;
        // Error shape #3: { signup_failed, why } — yet another invention
        if (password.Length < 8)
            return Results.Json(new { signup_failed = true, why = "password too short" }); // 200!

        if (!root.TryGetProperty("age", out var ageProp))
            return Results.Json(new { ok = false, problem = "no age" });                // 200!

        // GetInt32 throws if the client sent "age": "thirty" or 29.5 —
        // discovered in production, "fixed" with this try/catch.
        int age;
        try
        {
            age = ageProp.GetInt32();
        }
        catch (Exception)
        {
            return Results.Json(new { ok = false, problem = "age was not a whole number" }); // 200!
        }

        if (age < 13)
            return Results.Json(new { signup_failed = true, why = "too young" });       // 200!

        // Note what first-error-wins does to a user who got EVERYTHING wrong:
        // fix email → submit → "no password" → fix → submit → "too short" →
        // fix → submit → "too young". Four round trips to see four problems.
        return Results.Json(new { ok = true, message = $"welcome, {email}" });
    }
});

app.MapGet("/discount", (HttpRequest req) =>
{
    // Hand-parsing the query string. int.Parse THROWS on "?age=abc" — the
    // first version of this endpoint answered 500 until someone wrapped the
    // whole thing in this blanket try/catch.
    string? raw = req.Query["age"];
    try
    {
        var age = int.Parse(raw!);
        var percent = 0;
        if (age < 18) percent = 20;
        if (age >= 65) percent = 30;
        return Results.Json(new { age, percent });
    }
    catch (Exception)
    {
        return Results.Json(new { error = "bad age" });                                 // 200!
    }
});

app.Run("http://localhost:5017");

# 🏋️ Practice: Model Binding & Validation

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. A username field (warm-up)

Add `Username` to `SignupRequest` and validate it: required, 3–20 characters after trimming, and only
letters, digits, or `_`. Errors go under the `"username"` key, and a bad username must *accumulate*
alongside the other fields' errors. Update `Tests.cs`'s `V` helper for the extra parameter.
*Practices:* growing a DTO + adding an accumulated rule in the pure validator.
**Hint:** `username.All(c => char.IsAsciiLetterOrDigit(c) || c == '_')` checks the charset in one line.
**Check offline:** `Check.True(V("sam@site.com", "supersecret", 30, "ab").ContainsKey("username"), "2 chars is too short")` passes, and the happy-path tests still show zero errors.

### ⭐⭐ 2. Confirm the password (core)

Add `PasswordConfirm` to the DTO. When a password was supplied and the confirmation doesn't match it
exactly (case matters!), report `"passwords do not match"` under `"passwordConfirm"`. When the
password itself is missing, *don't* pile on a mismatch error too — one problem, one message.
*Practices:* cross-field validation — a rule that reads two fields at once.
**Hint:** guard with `password.Length > 0` before comparing; `req.PasswordConfirm != req.Password`
handles null-vs-value correctly for strings.
**Check offline:** add this Check test — it should pass:
`Check.True(V("s@x.com", "supersecret", 30, "sam", "supersecreT").ContainsKey("passwordConfirm"), "case matters");`

### ⭐⭐ 3. A shipping-cost endpoint (core)

Add `GET /shipping?weight=2.5` answering `{"weight":2.5,"cost":9.99}`. The policy, in a new pure
`ShippingRules.Cost(decimal weightKg)`: 0 or less → 0; up to 1 kg → 4.99; up to 5 kg → 9.99; up to
20 kg → 19.99; heavier → 49.99. `?weight=abc` must cost you *zero lines of parsing code*.
*Practices:* binding a `decimal` from the query + a switch expression with relational patterns.
**Hint:** copy `DiscountRules`' shape; relational patterns (`<= 1 =>`) work on `decimal` too.
**Check offline:** `Check.Equal(9.99m, ShippingRules.Cost(1.01m), "just over 1kg jumps a tier")` passes;
`curl -i "http://localhost:5017/shipping?weight=abc"` → `400` before your handler runs.

### ⭐⭐ 4. A second form: /feedback (core)

Add `POST /feedback` taking `{"message":"...","rating":4}`. Rules: message required, 10–500 chars
after trimming; rating required, 1–5. Same contract as `/signup`: all errors at once via
`Results.ValidationProblem`, `200` with a thank-you otherwise.
*Practices:* building a DTO + validator + endpoint trio from scratch — the project's whole pattern, solo.
**Hint:** three files' worth of pattern to imitate: record → static `Validate` → two-line endpoint.
**Check offline:** `curl -s -X POST http://localhost:5017/feedback -H "Content-Type: application/json" -d "{\"message\":\"short\",\"rating\":9}"` → one 400 whose `errors` has **both** `message` and `rating`.

### ⭐⭐⭐ 5. Password must not contain your email name (challenge)

`samantha@site.com` with password `xxSAMANTHAxx` is a gift to attackers. Add a rule: when the email
has text before its `@` (the *local part*) of 3+ characters, and the password (already 8+ chars)
contains that local part case-insensitively, add `"password must not contain your email name"` under
`"password"`. Shorter local parts are exempt (`ab@x.com` would forbid too much).
*Practices:* a cross-field rule with guards — and the pure validator is the only file that changes.
**Hint:** `email[..email.IndexOf('@')]` slices the local part; `Contains(localPart, StringComparison.OrdinalIgnoreCase)` compares.
**Check offline:** add this Check test — it should pass:
`Check.True(V("samantha@site.com", "xxSAMANTHAxx", 30).ContainsKey("password"), "email name inside password is rejected");`

## Solutions

### 1. Username

```csharp
// Signup.cs — the record grows
public record SignupRequest(string? Email, string? Password, int? Age, string? Username);

// Signup.cs — inside Validate, before `return errors;`
var username = req.Username?.Trim() ?? "";
var usernameErrors = new List<string>();
if (username.Length == 0)
    usernameErrors.Add("username is required");
else
{
    if (username.Length < 3 || username.Length > 20)
        usernameErrors.Add("username must be 3-20 characters");
    if (!username.All(c => char.IsAsciiLetterOrDigit(c) || c == '_'))
        usernameErrors.Add("username may only contain letters, digits, and _");
}
if (usernameErrors.Count > 0) errors["username"] = usernameErrors.ToArray();

// Tests.cs — the helper grows a defaulted parameter so old calls still compile
static Dictionary<string, string[]> V(string? email, string? password, int? age, string? username = "sam_99")
    => SignupValidator.Validate(new SignupRequest(email, password, age, username));
```

WHY: the DTO states what *may arrive*, the validator what's *acceptable* — so both change, nothing
else does. Note the two username rules are `if`+`if`, not `else if`: `"x!"` is both too short and
badly charactered, and accumulation applies within a field just like across fields.

### 2. Confirm password

```csharp
// Signup.cs — record (with exercise 1's field too)
public record SignupRequest(string? Email, string? Password, int? Age, string? Username, string? PasswordConfirm);

// Signup.cs — right after the password block
if (password.Length > 0 && req.PasswordConfirm != req.Password)
    errors["passwordConfirm"] = new[] { "passwords do not match" };

// Tests.cs — V grows once more; defaulting the confirmation to the password
// keeps every earlier test green without editing it
static Dictionary<string, string[]> V(string? email, string? password, int? age,
    string? username = "sam_99", string? passwordConfirm = null)
    => SignupValidator.Validate(new SignupRequest(email, password, age, username, passwordConfirm ?? password));
```

WHY: the guard makes the errors *independent*: a missing password already has its message, and adding
"doesn't match nothing" would just be noise. String `!=` is value comparison in C# (and `null != "x"`
is safely true), so the one-liner covers missing-confirmation and wrong-confirmation alike.

### 3. Shipping

```csharp
// ShippingRules.cs — new file, same shape as DiscountRules.cs
public static class ShippingRules
{
    public static decimal Cost(decimal weightKg) => weightKg switch
    {
        <= 0 => 0m,      // nonsense weights ship free rather than crash
        <= 1 => 4.99m,
        <= 5 => 9.99m,
        <= 20 => 19.99m,
        _ => 49.99m,
    };
}

// Program.cs
app.MapGet("/shipping", (decimal weight) => new { weight, cost = ShippingRules.Cost(weight) });
```

WHY: declaring `(decimal weight)` buys the same free 400 that `(int age)` bought `/discount` — the
handler never sees `abc`, and there is no `decimal.Parse` anywhere for a German locale or a typo to
break. The arms are ordered smallest-first because a `switch` takes the first arm that matches.

### 4. Feedback

```csharp
// Feedback.cs — new file
public record FeedbackRequest(string? Message, int? Rating);

public static class FeedbackValidator
{
    public static Dictionary<string, string[]> Validate(FeedbackRequest req)
    {
        var errors = new Dictionary<string, string[]>();

        var message = req.Message?.Trim() ?? "";
        var messageErrors = new List<string>();
        if (message.Length == 0) messageErrors.Add("message is required");
        else if (message.Length < 10) messageErrors.Add("message must be at least 10 characters");
        else if (message.Length > 500) messageErrors.Add("message must be 500 characters or fewer");
        if (messageErrors.Count > 0) errors["message"] = messageErrors.ToArray();

        var ratingErrors = new List<string>();
        if (req.Rating is not int rating) ratingErrors.Add("rating is required");
        else if (rating is < 1 or > 5) ratingErrors.Add("rating must be between 1 and 5");
        if (ratingErrors.Count > 0) errors["rating"] = ratingErrors.ToArray();

        return errors;
    }
}

// Program.cs
app.MapPost("/feedback", (FeedbackRequest body) =>
{
    var errors = FeedbackValidator.Validate(body);
    return errors.Count > 0
        ? Results.ValidationProblem(errors)
        : Results.Ok(new { message = "thanks for the feedback!" });
});
```

WHY: same skeleton as signup on purpose — a client that already handles one ProblemDetails 400 handles
this endpoint for free, which is the entire argument for the standard envelope. `rating is < 1 or 5`
would be a bug; `is < 1 or > 5` combines two relational patterns, and the `is not int rating` line is
the same null-unwrap trick the age rule uses.

### 5. Email name inside the password

```csharp
// Signup.cs — extend the password block (email was computed above it)
else if (password.Length < 8)
    passwordErrors.Add($"password must be at least 8 characters (got {password.Length})");
else
{
    var at = email.IndexOf('@');
    if (at > 0)
    {
        var localPart = email[..at];
        if (localPart.Length >= 3 && password.Contains(localPart, StringComparison.OrdinalIgnoreCase))
            passwordErrors.Add("password must not contain your email name");
    }
}
```

WHY: hanging the rule off the `else` chain means it only fires once length is satisfied — one problem
at a time *within* the chain, while still accumulating across fields. It reads `email`, which the
validator already normalized ten lines up: cross-field rules are trivial in a pure function and
miserable inside the original's stream-digging endpoint, which is the lesson in one sentence. The
3-character guard keeps the rule from banning half the alphabet for `ab@x.com`.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// Pure pricing rule — no HTTP, no parsing, just the decision.
// The endpoint declares `int age`, so by the time this runs, "abc" has
// already been rejected by the framework with an automatic 400.
public static class DiscountRules
{
    public static int Percent(int age) => age switch
    {
        < 0 => 0,      // nonsense ages get no discount rather than a crash
        < 18 => 20,    // kids and teens
        >= 65 => 30,   // seniors
        _ => 0,
    };
}

// Program.cs — the endpoints ask the framework for TYPED input and hand it
// to pure logic. Binding (JSON → record, query → int) is the framework's
// job; deciding what's valid is SignupValidator's job; both are visible here
// in two short endpoints.

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// The JSON body is bound into SignupRequest automatically. Unreadable JSON
// never reaches us — the framework answers 400 on its own.
app.MapPost("/signup", (SignupRequest body) =>
{
    var errors = SignupValidator.Validate(body);
    return errors.Count > 0
        ? Results.ValidationProblem(errors)                       // 400, standard shape, ALL errors
        : Results.Ok(new { message = $"welcome, {body.Email!.Trim()}" });
});

// Declaring `int age` makes the framework parse the query string and answer
// 400 on "?age=abc" by itself. This handler body never sees garbage.
app.MapGet("/discount", (int age) => new { age, percent = DiscountRules.Percent(age) });

app.Run("http://localhost:5017");

// The DTO: what a signup request looks like, stated once. The framework
// binds the JSON body into this record automatically — no JsonDocument,
// no TryGetProperty, no stream reading. Every field is nullable because
// clients omit fields; the VALIDATOR decides what that means.
public record SignupRequest(string? Email, string? Password, int? Age);

// SignupValidator — a pure function: request in, dictionary of problems out.
// Empty dictionary = valid. This is cs#08's accumulate-errors Result pattern:
// instead of bailing at the first problem (making the user fix-submit-repeat),
// we collect EVERY problem and report them all at once.
//
// The shape Dictionary<field, messages[]> is exactly what
// Results.ValidationProblem(...) wants — see Program.cs.
public static class SignupValidator
{
    public static Dictionary<string, string[]> Validate(SignupRequest req)
    {
        var errors = new Dictionary<string, string[]>();

        // --- email ---
        var email = req.Email?.Trim() ?? "";
        var emailErrors = new List<string>();
        if (email.Length == 0)
            emailErrors.Add("email is required");
        else
        {
            if (email.Contains(' '))
                emailErrors.Add("email must not contain spaces");
            var at = email.IndexOf('@');
            if (at <= 0 || at != email.LastIndexOf('@') || at == email.Length - 1)
                emailErrors.Add("email must be text@text — exactly one @, text on both sides");
            else if (!email[(at + 1)..].Contains('.'))
                emailErrors.Add("email needs a dot after the @, like name@site.com");
        }
        if (emailErrors.Count > 0) errors["email"] = emailErrors.ToArray();

        // --- password ---
        var password = req.Password ?? "";
        var passwordErrors = new List<string>();
        if (password.Length == 0)
            passwordErrors.Add("password is required");
        else if (password.Length < 8)
            passwordErrors.Add($"password must be at least 8 characters (got {password.Length})");
        if (passwordErrors.Count > 0) errors["password"] = passwordErrors.ToArray();

        // --- age ---
        var ageErrors = new List<string>();
        if (req.Age is not int age)
            ageErrors.Add("age is required");
        else if (age < 13)
            ageErrors.Add("you must be at least 13 to sign up");
        else if (age > 120)
            ageErrors.Add("age looks implausible (must be 120 or less)");
        if (ageErrors.Count > 0) errors["age"] = ageErrors.ToArray();

        return errors;
    }
}

// Tests.cs — every validation rule, exercised as a pure function.
// The original's rules lived inside an endpoint reading a body stream:
// testing "is 12 too young?" required a running server and a crafted
// HTTP request. Here it's a method call.
public static class Tests
{
    static Dictionary<string, string[]> V(string? email, string? password, int? age)
        => SignupValidator.Validate(new SignupRequest(email, password, age));

    public static int Run()
    {
        Console.WriteLine("SignupValidator — happy path");
        Check.Equal(0, V("sam@site.com", "supersecret", 30).Count, "a valid signup has zero errors");
        Check.Equal(0, V("  sam@site.com  ", "12345678", 13).Count, "email is trimmed; 8-char password and age 13 are the boundaries");

        Console.WriteLine("SignupValidator — email rules");
        Check.True(V(null, "supersecret", 30).ContainsKey("email"), "missing email is reported under 'email'");
        Check.True(V("   ", "supersecret", 30).ContainsKey("email"), "blank email is an error");
        Check.True(V("plainaddress", "supersecret", 30).ContainsKey("email"), "no @ at all");
        Check.True(V("@site.com", "supersecret", 30).ContainsKey("email"), "nothing before the @");
        Check.True(V("sam@", "supersecret", 30).ContainsKey("email"), "nothing after the @");
        Check.True(V("sam@site", "supersecret", 30).ContainsKey("email"), "no dot after the @");
        Check.True(V("sam@@site.com", "supersecret", 30).ContainsKey("email"), "two @ signs");
        Check.True(V("sam smith@site.com", "supersecret", 30).ContainsKey("email"), "spaces inside");
        Check.True(!V("sam@site.co.uk", "supersecret", 30).ContainsKey("email"), "several dots after the @ are fine");

        Console.WriteLine("SignupValidator — password rules");
        Check.True(V("sam@site.com", null, 30).ContainsKey("password"), "missing password");
        Check.True(V("sam@site.com", "seven77", 30).ContainsKey("password"), "7 characters is too short");
        Check.True(!V("sam@site.com", "eight888", 30).ContainsKey("password"), "exactly 8 characters passes");

        Console.WriteLine("SignupValidator — age rules");
        Check.True(V("sam@site.com", "supersecret", null).ContainsKey("age"), "missing age");
        Check.True(V("sam@site.com", "supersecret", 12).ContainsKey("age"), "12 is too young");
        Check.True(!V("sam@site.com", "supersecret", 13).ContainsKey("age"), "13 is allowed");
        Check.True(!V("sam@site.com", "supersecret", 120).ContainsKey("age"), "120 is allowed");
        Check.True(V("sam@site.com", "supersecret", 121).ContainsKey("age"), "121 is implausible");

        Console.WriteLine("SignupValidator — errors ACCUMULATE (the whole point)");
        var all = V("not-an-email", "pw", 5);
        Check.Equal(3, all.Count, "three broken fields → three error keys in ONE response");
        Check.True(all.ContainsKey("email") && all.ContainsKey("password") && all.ContainsKey("age"),
            "every broken field is reported, not just the first");
        Check.Equal(2, V("a b@c", "supersecret", 30)["email"].Length,
            "one field can carry two messages (spaces AND missing dot)");

        Console.WriteLine("DiscountRules");
        Check.Equal(20, DiscountRules.Percent(10), "kids get 20%");
        Check.Equal(20, DiscountRules.Percent(17), "17 still counts as under 18");
        Check.Equal(0, DiscountRules.Percent(18), "18 pays full price");
        Check.Equal(0, DiscountRules.Percent(64), "64 pays full price");
        Check.Equal(30, DiscountRules.Percent(65), "65 gets the senior 30%");
        Check.Equal(30, DiscountRules.Percent(90), "so does 90");
        Check.Equal(0, DiscountRules.Percent(-5), "negative ages get 0, not a crash");

        return Check.Summary();
    }
}
